null,"postal":null,"category":"Snow Removal","search_type":"yellowpages-ca","source_status":""},{"n":353,"name":"ALC Snow Removal","phone":"4168763256","email":"","website":"","address":"","city":null,"postal":null,"category":"Snow Removal","search_type":"yellowpages-ca","source_status":""},{"n":354,"name":"Plow One","phone":"5196529537","email":"","website":"","address":"","city":null,"postal":null,"category":"Snow Removal","search_type":"yellowpages-ca","source_status":""},{"n":355,"name":"Mississauga Snow Removal","phone":"6473819936","email":"","website":"","address":"","city":null,"postal":null,"category":"Snow Removal","search_type":"yellowpages-ca","source_status":""},{"n":356,"name":"Richard''s Lawn Cutting & Snow Removal Services","phone":"5196080338","email":"","website":"","address":"","city":null,"postal":null,"category":"Landscape Contractors & Designers","search_type":"yellowpages-ca","source_status":""},{"n":357,"name":"Christian Snow Removal &amp; Landscape","phone":"2894569630","email":"","website":"","address":"Hamilton, ON L8R 2K8","city":null,"postal":"L8R 2K8","category":"Snow Removal,Landscape Contractors & Designers","search_type":"yellowpages-ca","source_status":""},{"n":358,"name":"Rukavina Landscape & Property Services","phone":"6477826559","email":"","website":"","address":"Toronto, ON M1H 1K9","city":"Toronto","postal":"M1H 1K9","category":"Landscaping,Snow Removal","search_type":"yelp","source_status":""},{"n":359,"name":"Tree Monkey Tree Removal","phone":"7057600627","email":"","website":"","address":"","city":null,"postal":null,"category":"Snow Removal,Property Maintenance","search_type":"yellowpages-ca","source_status":""}]'::jsonb)
 as r(n integer,name text,phone text,email text,website text,address text,city text,postal text,category text,search_type text,source_status text);
create temporary table snow_classified on commit drop as
select x.*,
 case when x.duplicate_in_file then 'duplicate_skipped'
      when x.existing_match then 'existing_matched'
      when x.phone_key = '' or x.shared_phone or x.shared_website or x.name_key = '' or x.off_category or x.generic_name
        or (x.website is not null and x.website !~* '^https?://[^ /]+\.[^ /]+')
        or x.dnc_match then 'review_required'
      when x.website is null then 'no_website'
      else 'website_review' end as bucket,
 concat_ws('; ',case when x.phone_key='' then 'Missing phone' end,
   case when x.shared_phone then 'Shared phone in CSV' end,
   case when x.shared_website then 'Shared website in CSV' end,
   case when x.generic_name then 'Generic business name; verify identity' end,
   case when x.off_category then 'Snow removal service not established by category/name' end,
   case when x.website is not null and x.website !~* '^https?://[^ /]+\.[^ /]+' then 'Website URL unclear' end,
   case when x.dnc_match then 'DNC suppression' end) as review_reason
from (
 select s.*,
 row_number() over(partition by s.name_key order by s.n)>1 as duplicate_in_file,
 s.phone_key<>'' and exists(select 1 from snow_source other where other.phone_key=s.phone_key and other.name_key<>s.name_key) as shared_phone,
 s.website_key<>'' and exists(select 1 from snow_source other where other.website_key=s.website_key and other.name_key<>s.name_key) as shared_website,
 s.name_key in ('snowremovalservices','snowremovalservice','snowremovaltoronto','landscapingservices') as generic_name,
 not (coalesce(s.name,'') ~* '(snow|winter|ice removal|plow|landscap|lawn|yard|garden|property maintenance|property care|outdoor|grounds|excavat|paving|driveway)'
   or coalesce(s.category,'') ~* '(snow|winter|plow|landscap|lawn|yard|garden|property maintenance|grounds|excavat|paving)') as off_category,
 exists(select 1 from public.call_list_leads l where regexp_replace(lower(l.business_name),'[^a-z0-9]','','g')=s.name_key
   or (s.phone_key<>'' and right(regexp_replace(coalesce(l.phone,''),'[^0-9]','','g'),10)=s.phone_key)
   or (s.website_key<>'' and regexp_replace(regexp_replace(lower(coalesce(l.website,'')),'^https?://(www\.)?','','g'),'/$','','g')=s.website_key))
 or exists(select 1 from public.leadgen_leads l where regexp_replace(lower(l.business_name),'[^a-z0-9]','','g')=s.name_key
   or (s.phone_key<>'' and right(regexp_replace(coalesce(l.phone,''),'[^0-9]','','g'),10)=s.phone_key)
   or (s.website_key<>'' and regexp_replace(regexp_replace(lower(coalesce(l.website,'')),'^https?://(www\.)?','','g'),'/$','','g')=s.website_key)) as existing_match,
 exists(select 1 from public.crm_dnc_suppressions d where d.status='active' and d.removed_at is null
   and d.block_phone=true and s.phone_key<>'' and right(d.normalized_phone,10)=s.phone_key) as dnc_match
 from snow_source s
) x;
do $snow$
declare
  v_client uuid;
  v_henry uuid;
  v_admin uuid;
  v_campaign uuid;
  v_no uuid;
  v_web uuid;
  v_review uuid;
begin
  if exists (select 1 from public.call_list_segments where crm='lead_generation' and source_file_name='campaign-125286-search-924568-snow-removal-service_toronto-on-canada_abe4e4a9875a10ccbd8df28a4f258826.csv') then
    raise exception 'Snow Removal source file already imported; inspect existing segments before retrying';
  end if;
  select id into strict v_client from public.leadgen_clients where name='Teknokraft Canada Inc.' and active=true;
  select id into strict v_henry from auth.users where email='henryosuji2@gmail.com';
  select id into strict v_admin from auth.users where email='cjamadiwins@gmail.com';

  insert into public.leadgen_campaigns
    (client_id,name,description,status,territory,target_industry,assigned_team,start_date,created_by)
  values (v_client,'Teknokraft Canada Inc. — Toronto Snow Removal',
    'Toronto snow removal website design and SEO prospecting; Henry Osuji. Individual eligible leads may be reassigned by Admin without duplicating records.',
    'active','Toronto, Ontario','Snow Removal Services','Henry Osuji','2026-10-01',v_admin)
  returning id into v_campaign;

  insert into public.call_list_segments
    (crm,name,leadgen_campaign_id,status,created_by,campaign_name,industry,territory,source_file_name,source_file_type,total_uploaded_rows,deployed_at,deployed_by)
  values ('lead_generation','Snow Removal — No Website — Henry Osuji',v_campaign,'active',v_admin,
      'Teknokraft Canada Inc. — Toronto Snow Removal','Snow Removal Services','Toronto, Ontario','campaign-125286-search-924568-snow-removal-service_toronto-on-canada_abe4e4a9875a10ccbd8df28a4f258826.csv','csv',0,now(),v_admin)
  returning id into v_no;
  insert into public.call_list_segments
    (crm,name,leadgen_campaign_id,status,created_by,campaign_name,industry,territory,source_file_name,source_file_type,total_uploaded_rows,deployed_at,deployed_by)
  values ('lead_generation','Snow Removal — Website Review — Henry Osuji',v_campaign,'active',v_admin,
      'Teknokraft Canada Inc. — Toronto Snow Removal','Snow Removal Services','Toronto, Ontario','campaign-125286-search-924568-snow-removal-service_toronto-on-canada_abe4e4a9875a10ccbd8df28a4f258826.csv','csv',0,now(),v_admin)
  returning id into v_web;
  insert into public.call_list_segments
    (crm,name,leadgen_campaign_id,status,created_by,campaign_name,industry,territory,source_file_name,source_file_type,total_uploaded_rows)
  values ('lead_generation','Snow Removal — Review Required — Admin Only',v_campaign,'draft',v_admin,
      'Teknokraft Canada Inc. — Toronto Snow Removal','Snow Removal Services','Toronto, Ontario','campaign-125286-search-924568-snow-removal-service_toronto-on-canada_abe4e4a9875a10ccbd8df28a4f258826.csv','csv',0)
  returning id into v_review;

  insert into public.call_list_segment_agents(segment_id,agent_id)
  values (v_no,v_henry),(v_web,v_henry);

  insert into public.call_list_leads
    (segment_id,source_row_number,business_name,phone,email,website,street_address,city,province,postal_code,country,industry,notes,
     extra_fields,is_possible_duplicate,duplicate_reason,dnc_flag,assigned_agent_id,created_by)
  select case bucket when 'no_website' then v_no when 'website_review' then v_web else v_review end,
    n,name,phone,email,website,address,city,'ON',postal,'Canada','Snow Removal Services',
    case bucket when 'no_website' then 'No website URL in source; verify before outreach.'
      when 'website_review' then 'Website present; review for redesign, presentation and SEO opportunity without presuming a defect.'
      else review_reason end,
    jsonb_build_object('source_file','campaign-125286-search-924568-snow-removal-service_toronto-on-canada_abe4e4a9875a10ccbd8df28a4f258826.csv','source_address',address,
      'source_category',category,'source_search_type',search_type,'source_status',source_status,
      'website_category',bucket,'review_reason',review_reason),
    (shared_phone or shared_website),case when shared_phone or shared_website then review_reason end,dnc_match,
    case when bucket in ('no_website','website_review') then v_henry else null end,v_admin
  from snow_classified where bucket in ('no_website','website_review','review_required');

  update public.call_list_segments s
  set total_uploaded_rows=(select count(*) from public.call_list_leads l where l.segment_id=s.id)
  where s.id in (v_no,v_web,v_review);
end;
$snow$;
